ge:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"You are the original Personality of Godhead, the oldest, the ultimate sanctuary of this manifested cosmic world. You are the knower of everything, and You are all that is knowable. You are the supreme refuge, above the material modes. O limitless form! This whole cosmic manifestation is pervaded by You!\"}}]}]}]]]}]\n2e:[\"$\",\"div\",\"3336-purport,3336-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L29\",\"child-3341\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Everything is resting on the Supreme Personality of Godhead; therefore He is the ultimate rest. Nidhānam means that everything, even the Brahman effulgence, rests on the Supreme Personality of Godhead, Kṛṣṇa. He is the knower of everything that is happening in this world, and if knowledge has any end, He is the end of all knowledge; therefore He is the known and the knowable. He is the object of knowledge because He is all-pervading. Because He is the cause in the spiritual world, He is transcendental. He is also the chief personality in the transcendental world.\"}}]}]]]}]\n37:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"26:[\"$\",\"div\",null,{\"id\":\"footer\",\"cla