प्रजापतिस्त्वं प्रपितामहश्च ।
नमो नमस्तेऽस्तु सहस्रकृत्व:
पुनश्च भूयोऽपि नमो नमस्ते ॥ ३९ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3344,\"bb\":2945,\"url_path\":\"/en/library/bg/11/39/b2945/\",\"body_value\":\"vāyur yamo ’gnir varuṇaḥ śaśāṅkaḥ
prajāpatis tvaṁ prapitāmahaś ca
namo namas te ’stu sahasra-kṛtvaḥ
punaś ca bhūyo ’pi namo namas te\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3345,\"bb\":2946,\"url_path\":\"/en/library/bg/11/39/b2946/\",\"shadow_value\":\"vāyuḥ – air; yamaḥ – the controller; agniḥ – fire; varuṇaḥ – water; śaśa-aṅkaḥ – the moon; prajāpatiḥ – Brahmā; tvam – You; prapitāmahaḥ – the great-grandfather; ca – also; namaḥ – my respects; namaḥ – again my respects; te – unto You; astu – let there be; sahasra-kṛtvaḥ – a thousand times; punaḥ ca – and again; bhūyaḥ – again; api – also; namaḥ – offering my respects; namaḥ te – offering my respects unto You.\",\"word_for_word_value\":[{\"word\":\"vāyuḥ\",\"translation\":\"air\"},{\"word\":\"yamaḥ\",\"translation\":\"the controller\"},{\"word\":\"agniḥ\",\"translation\":\"fire\"},{\"word\":\"varuṇaḥ\",\"translation\":\"water\"},{\"word\":\"śaśa-aṅkaḥ\",\"translation\":\"the moon\"},{\"word\":\"prajāpatiḥ\",\"translation\":\"Brahmā\"},{\"word\":\"tvam\",\"translation\":\"You\"},{\"word\":\"prapitāmahaḥ\",\"translation\":\"the great-grandfather\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"namaḥ\",\"translation\":\"my respects\"},{\"word\":\"namaḥ\",\"translation\":\"again my respects\"},{\"word\":\"te\",\"translation\":\"unto You\"},{\"word\":\"astu\",\"translation\":\"let there be\"},{\"word\":\"sahasra-kṛtvaḥ\",\"translation\":\"a thousand times\"},{\"word\":\"punaḥ ca\",\"translation\":\"and again\"},{\"word\":\"bhūyaḥ\",\"translation\":\"again\"},{\"word\":\"api\",\"translation\":\"also\"},{\"word\":\"namaḥ\",\"translation\":\"offering my respects\"},{\"word\":\"namaḥ te\",\"translation\":\"offering my respects unto You\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3346,\"bb\":2947,\"url_path\":\"/en/library/bg/11/39/b2947/\",\"body_value\":\"You are air, and You are the supreme controller! You are fire, You are water, and You are the moon! You are Brahmā, the first living creature, and You are the great-grandfather. I therefore offer my respectful obeisances unto You a thousand times, and again and yet again!\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3347,\"bb\":2948,\"url_path\":\"/en/library/bg/11/39/b2948/\",\"body_value\":\"The Lord is addressed here as air because the air is the most important representation of all the demigods, being all-pervasive. Arjuna also addresses Kṛṣṇa as the great-grandfather because He is the father of Brahmā, the first living creature in the universe.\"}]}],\"short_title\":\"Bg. 11.39\",\"medium_title\":\"Bhagavad-gītā As It Is 11.39\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"