नमोऽस्तु ते सर्वत एव सर्व ।
अनन्तवीर्यामितविक्रमस्त्वं
सर्वं समाप्‍नोषि ततोऽसि सर्व: ॥ ४० ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3350,\"bb\":2950,\"url_path\":\"/en/library/bg/11/40/b2950/\",\"body_value\":\"namaḥ purastād atha pṛṣṭhatas te
namo ’stu te sarvata eva sarva
ananta-vīryāmita-vikramas tvaṁ
sarvaṁ samāpnoṣi tato ’si sarvaḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3351,\"bb\":2951,\"url_path\":\"/en/library/bg/11/40/b2951/\",\"shadow_value\":\"namaḥ – offering obeisances; purastāt – from the front; atha – also; pṛṣṭhataḥ – from behind; te – unto You; namaḥ astu – I offer my respects; te – unto You; sarvataḥ – from all sides; eva – indeed; sarva – because You are everything; ananta-vīrya – unlimited potency; amita-vikramaḥ – and unlimited force; tvam – You; sarvam – everything; samāpnoṣi – You cover; tataḥ – therefore; asi – You are; sarvaḥ – everything.\",\"word_for_word_value\":[{\"word\":\"namaḥ\",\"translation\":\"offering obeisances\"},{\"word\":\"purastāt\",\"translation\":\"from the front\"},{\"word\":\"atha\",\"translation\":\"also\"},{\"word\":\"pṛṣṭhataḥ\",\"translation\":\"from behind\"},{\"word\":\"te\",\"translation\":\"unto You\"},{\"word\":\"namaḥ astu\",\"translation\":\"I offer my respects\"},{\"word\":\"te\",\"translation\":\"unto You\"},{\"word\":\"sarvataḥ\",\"translation\":\"from all sides\"},{\"word\":\"eva\",\"translation\":\"indeed\"},{\"word\":\"sarva\",\"translation\":\"because You are everything\"},{\"word\":\"ananta-vīrya\",\"translation\":\"unlimited potency\"},{\"word\":\"amita-vikramaḥ\",\"translation\":\"and unlimited force\"},{\"word\":\"tvam\",\"translation\":\"You\"},{\"word\":\"sarvam\",\"translation\":\"everything\"},{\"word\":\"samāpnoṣi\",\"translation\":\"You cover\"},{\"word\":\"tataḥ\",\"translation\":\"therefore\"},{\"word\":\"asi\",\"translation\":\"You are\"},{\"word\":\"sarvaḥ\",\"translation\":\"everything\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3352,\"bb\":2952,\"url_path\":\"/en/library/bg/11/40/b2952/\",\"body_value\":\"Obeisances to You from the front, from behind and from all sides! O unbounded power, You are the master of limitless might! You are all-pervading, and thus You are everything!\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3353,\"bb\":2953,\"url_path\":\"/en/library/bg/11/40/b2953/\",\"body_value\":\"Out of loving ecstasy for Kṛṣṇa, his friend, Arjuna is offering his respects from all sides. He is accepting that He is the master of all potencies and all prowess and far superior to all the great warriors assembled on the battlefield. It is said in the Viṣṇu Purāṇa (1.9.69):\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3354,\"bb\":2954,\"url_path\":\"/en/library/bg/11/40/b2954/\",\"body_value\":\"yo ’yaṁ tavāgato deva
samīpaṁ devatā-gaṇaḥ
sa tvam eva jagat-sraṣṭā
yataḥ sarva-gato bhavān\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3355,\"bb\":2955,\"url_path\":\"/en/library/bg/11/40/b2955/\",\"body_value\":\"“Whoever comes before You, even if he be a demigod, is created by You, O Supreme Personality of Godhead.”\"}]}],\"short_title\":\"Bg. 11.40\",\"medium_title\":\"Bhagavad-gītā As It Is 11.40\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"Bhagavad-gītā As It Is\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/11/\",{\"className\":\"inline\",\